// single-item input: Settings emits one row and the app list is read from it.
const cfg = $('Settings').first().json;

const urls = String(cfg.app_store_urls || '')
  .split(/[|,\s]+/)
  .map(function (u) { return u.trim(); })
  .filter(function (u) { return u.indexOf('apps.apple.com') >= 0; });

if (!urls.length) {
  throw new Error('Put at least one App Store URL in app_store_urls, for example https://apps.apple.com/us/app/things-3/id904237743');
}

const cap = Math.max(1, Math.min(40, Number(cfg.max_apps) || 15));
const chosen = urls.slice(0, cap);

// The whole list is one trigger call. The Web Scraper API takes an array, and
// three listings came back in under twenty seconds on 2026-08-27, so there is no
// reason to split them.
return [{ json: {
  payload: chosen.map(function (u) { return { url: u }; }),
  requested: chosen.length,
  skipped: urls.length - chosen.length,
}}];

// Bright Data answers validation errors and rate limits with HTTP 200 and an
// error body, and neverError means nothing throws. Left unchecked, snapshot_id
// is undefined, the progress URL becomes .../progress/undefined, and the failure
// shows up two nodes later blaming the wrong thing.
//
// single-item input: one trigger call returns one snapshot id.
const res = $input.first().json;
if (res.error || !res.snapshot_id) {
  throw new Error('Bright Data did not accept the request: ' + JSON.stringify(res).slice(0, 400));
}
return [{ json: { snapshot_id: res.snapshot_id } }];

// The poll cap lives here rather than on the Wait node, because a Wait has no
// idea how many times it has run. $runIndex is the poll count.
const MAX_POLLS = Math.max(3, Number($('Settings').first().json.max_polls) || 20);

// single-item input: the progress endpoint returns one status object.
const res = $input.first().json;
const attempt = $runIndex + 1;

if (res.error) {
  throw new Error('Progress check failed: ' + JSON.stringify(res.error));
}
if (res.status === 'failed') {
  throw new Error('Bright Data reported the snapshot failed: ' + JSON.stringify(res).slice(0, 400));
}
if (res.status !== 'ready' && attempt >= MAX_POLLS) {
  throw new Error(
    'The listing snapshot was still ' + res.status + ' after ' + attempt +
    ' polls. Raise max_polls in Settings, or shorten app_store_urls.'
  );
}
return [{ json: { status: res.status, attempt: attempt } }];

// Flatten a listing into the eleven fields worth diffing, and normalise every
// one of them on the way past.
//
// The snapshot is requested with include_errors=true, which is right - a page
// that failed should be visible rather than silently absent - but it means the
// snapshot contains rows that are nothing but an error. Five of thirty review
// rows in testing were {"error":"Crawl aborted on job cancel"} and no other
// field. Dropping on the presence of the field this node needs is the only
// filter that survives whatever shape the next failure takes.
const rows = $input.all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && r.app_id && r.title; });

const failed = $input.all().length - rows.length;
if (!rows.length) {
  throw new Error('Every listing row came back empty or errored. Check that the App Store URLs in Settings still resolve.');
}

// No crypto in the Code node sandbox, so this is djb2 - fourteen lines, stable
// across runs, and all that is needed to answer "is this the same text".
function hash(s) {
  let h = 5381;
  const t = String(s || '');
  for (let i = 0; i < t.length; i++) {
    h = ((h << 5) + h + t.charCodeAt(i)) | 0;
  }
  return String(h >>> 0);
}

function clean(s) {
  return String(s === null || s === undefined ? '' : s).replace(/\s+/g, ' ').trim();
}

const out = rows.map(function (r) {
  const stars = r.reviews_star_percentage || {};
  const desc = clean(r.description);

  // monetization_features carries "In-App Purchases" with a NON-BREAKING hyphen
  // (U+2011), so a match on the ASCII spelling finds nothing. Normalising every
  // dash-like character to a plain one before comparing is the fix, and it also
  // covers the en dash that turns up in price strings.
  const money = (r.monetization_features || [])
    .map(function (m) { return clean(m).replace(/[\u2010-\u2015]/g, '-'); })
    .join(', ');

  return { json: {
    app_id: String(r.app_id),
    title: clean(r.title),
    url: String(r.url || ''),
    // "Version 3.23.1" from the listing dataset, bare "1.7.283" from the review
    // one. Strip the word so the stored value means the same thing either way.
    version: clean(r.latest_app_version).replace(/^version\s+/i, ''),
    price: clean(r.price),
    monetization: money,
    iap_count: (r.In_app_purchases || []).length,
    sub_title: clean(r.sub_title),
    // The store shows roughly this much above the fold, and it is what the model
    // is handed when the pitch changes - storing the whole description would put
    // four kilobytes in a Data Table cell for no extra signal.
    desc_head: desc.slice(0, 900),
    desc_hash: hash(desc),
    desc_chars: desc.length,
    screenshots: (r.screenshots || []).length,
    languages: (r.languages || []).map(clean).filter(Boolean).sort().join(', '),
    language_count: (r.languages || []).length,
    size_mb: clean(r.size),
    rating: r.rating === null || r.rating === undefined ? null : Number(r.rating),
    // Rounded to the nearest thousand by Apple, so this is a trend and not a
    // count. Never present it as one.
    raters: Number(r.number_of_raters) || 0,
    one_star: Number(stars.one_stars) || 0,
    five_star: Number(stars.five_stars) || 0,
    editorial: (r.top_charts || []).concat(r.featured_in || []).length,
    failed_rows: failed,
  }};
});

return out;

// Compare this week's listing to what was stored, field by field.
//
// The history arrives on $input because the Data Table read sits directly above;
// this week's listings are pulled by name. alwaysOutputData is on that read, so
// an empty table on the first run arrives as one item with no app_id - filtering
// on the field is what turns that into an empty history rather than a row keyed
// on undefined.
const history = {};
$input.all().forEach(function (i) {
  if (i.json && i.json.app_id) history[String(i.json.app_id)] = i.json;
});

const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
const current = $('Read Each Listing').all().map(function (i) { return i.json; });

function num(v) { return v === null || v === undefined || v === '' ? null : Number(v); }

// Which fields are worth waking somebody up for, and how to describe a move in
// each. Rating and the star shares get a threshold because Apple reports them
// coarsely - whole percentages on a rounded rater count - so a one-point wobble
// is noise dressed as news.
function diff(prev, cur) {
  const changes = [];
  function txt(field, label) {
    const a = String(prev[field] === undefined ? '' : prev[field]);
    const b = String(cur[field] === undefined ? '' : cur[field]);
    if (a && a !== b) changes.push({ field: label, from: a, to: b, kind: 'text' });
  }
  function count(field, label) {
    const a = num(prev[field]);
    const b = num(cur[field]);
    if (a !== null && b !== null && a !== b) {
      changes.push({ field: label, from: String(a), to: String(b), kind: 'count', delta: b - a });
    }
  }

  txt('version', 'version');
  txt('price', 'price');
  txt('sub_title', 'subtitle');
  txt('languages', 'languages');
  count('screenshots', 'screenshots');

  if (prev.desc_hash && cur.desc_hash && String(prev.desc_hash) !== String(cur.desc_hash)) {
    changes.push({
      field: 'description', kind: 'text',
      from: String(prev.desc_head || ''), to: String(cur.desc_head || ''),
    });
  }

  const r0 = num(prev.rating);
  const r1 = num(cur.rating);
  if (r0 !== null && r1 !== null && Math.abs(r1 - r0) >= 0.1) {
    changes.push({ field: 'rating', from: String(r0), to: String(r1), kind: 'count', delta: Math.round((r1 - r0) * 10) / 10 });
  }

  const s0 = num(prev.one_star);
  const s1 = num(cur.one_star);
  if (s0 !== null && s1 !== null && Math.abs(s1 - s0) >= 1) {
    changes.push({ field: 'one-star share', from: s0 + '%', to: s1 + '%', kind: 'count', delta: s1 - s0 });
  }

  return changes;
}

return current.map(function (c) {
  const prev = history[c.app_id];
  const first = !prev;
  const changes = first ? [] : diff(prev, c);
  return { json: Object.assign({}, c, {
    checked_at: now,
    first_seen: first,
    changed: changes.length > 0,
    change_count: changes.length,
    changes: changes,
    // The headline is picked in code rather than by the model, so the digest
    // reads the same way every week even when the model is having an off day.
    headline: changes.length
      ? changes.map(function (x) { return x.field; }).join(', ')
      : (first ? 'first seen' : 'no change'),
  })};
});

// One item for the whole run, so the IF below is a single decision rather than
// one decision per app.
const rows = $input.all().map(function (i) { return i.json; });
const cfg = $('Settings').first().json;

const cap = Math.max(1, Math.min(15, Number(cfg.max_explained) || 8));
const moved = rows.filter(function (r) { return r.changed; });

// Ranked so the cap spends the model budget on the apps that moved most, not on
// whichever happened to be pasted first in Settings.
moved.sort(function (a, b) { return b.change_count - a.change_count; });

return [{ json: {
  has_changes: moved.length > 0,
  moved_count: moved.length,
  watched: rows.length,
  first_run: rows.length > 0 && rows.every(function (r) { return r.first_seen; }),
  not_explained: Math.max(0, moved.length - cap),
  failed_rows: rows.length ? rows[0].failed_rows : 0,
  changed: moved.slice(0, cap).map(function (r) {
    return {
      app_id: r.app_id,
      title: r.title,
      url: r.url,
      version: r.version,
      headline: r.headline,
      change_count: r.change_count,
      changes: r.changes,
    };
  }),
}}];

parameters.text:
=An App Store listing changed since last week. Say what the change means for a competitor watching it.

App: {{ $json.title }}
Current version: {{ $json.version }}

What moved, as JSON:
{{ JSON.stringify($json.changes, null, 1) }}

Write two sentences, maximum forty words total, no heading and no bullet list.
- The first says what changed, concretely, quoting the new wording when the subtitle or description moved.
- The second says what it suggests they are doing - a repositioning, a price test, a new market, a bug they are fixing - and only if the change actually supports it.
A version number on its own supports nothing. If all that moved is the version, say that it is a routine release and stop.
Do not speculate about revenue, downloads or strategy that is not visible in the fields above.

