// One message for the run. The Split Out above turned the summary into one item
// per changed app, so the readings are collected back by name.
const summary = $('Summarise The Week').first().json;
const notes = {};
$input.all().forEach(function (item, idx) {
  const src = $('One App At A Time').all()[idx];
  if (!src) return;
  const text = String((item.json || {}).text || '').replace(/\s+/g, ' ').trim();
  if (text) notes[src.json.app_id] = text;
});

const ICON = {
  price: ':heavy_dollar_sign:',
  subtitle: ':pencil2:',
  description: ':page_facing_up:',
  languages: ':globe_with_meridians:',
  screenshots: ':frame_with_picture:',
  version: ':package:',
};

const lines = [];
lines.push('*App Store listing changes* - ' + summary.moved_count + ' of ' +
  summary.watched + ' watched apps moved this week.');

summary.changed.forEach(function (a) {
  const icons = a.changes.map(function (c) { return ICON[c.field] || ':small_blue_diamond:'; });
  const seen = {};
  const uniq = icons.filter(function (i) { if (seen[i]) return false; seen[i] = true; return true; });
  lines.push('');
  lines.push(uniq.join('') + ' *<' + a.url + '|' + a.title + '>* - ' + a.headline);
  a.changes.forEach(function (c) {
    if (c.field === 'description') {
      lines.push('    _description rewritten_');
    } else if (c.kind === 'text') {
      lines.push('    ' + c.field + ': `' + String(c.from).slice(0, 70) +
        '` -> `' + String(c.to).slice(0, 70) + '`');
    } else {
      lines.push('    ' + c.field + ': ' + c.from + ' -> ' + c.to +
        ' (' + (c.delta > 0 ? '+' : '') + c.delta + ')');
    }
  });
  if (notes[a.app_id]) lines.push('    > ' + notes[a.app_id]);
});

if (summary.not_explained) {
  lines.push('');
  lines.push('_' + summary.not_explained + ' more app(s) changed but were not written up - raise max_explained in Settings._');
}
if (summary.failed_rows) {
  lines.push('_' + summary.failed_rows + ' listing(s) failed to scrape this run and were skipped._');
}
lines.push('');
lines.push('_Rater counts are rounded to the nearest thousand and star shares are whole percentages, so small moves are invisible._');

return [{ json: { message: lines.join('\n') } }];
